SINA_SMART["physics1-migration"] = {"lecture":"physics1-migration","title":"Migration movements: sedimentation, centrifugation, electrophoresis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physics1-migration:e0","text":"Migration: some particles move, the solvent stays.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-migration:e4","text":"Centrifugal acceleration γ = ω²R ≫ g.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-migration:e1","text":"Stokes: R = −6πrηv for a sphere; velocity becomes constant.","topic":"Drag and sedimentation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-migration:e2","text":"Sedimentation force = V·g(ρ_s − ρ₀) (weight − Archimedes).","topic":"Drag and sedimentation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-migration:e3","text":"ESR: plasma height after 1 h; normal < 10 mm; ↑ inflammation.","topic":"Drag and sedimentation","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-migration:e5","text":"Electric field: F = qE; v = uE; flux Φ = C·S·v.","topic":"Centrifugation and electrophoresis","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-migration:e6","text":"Electrophoresis separates proteins by charge, size, shape.","topic":"Centrifugation and electrophoresis","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"jfijvx":"a","1ayoz0c":"a","k5vjp9":"a","y86zre":"a","90jfcg":"a","bwa2sv":"a","r6xztv":"a","v5siux":"a","1omffzz":"a","19z431h":"a"},"mapCounts":{"verified":0,"auto":10,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physics1-migration:e0":{"s":0,"u":["Migration: some particles move, the solvent stays.","A migration movement is the movement of some particles while others (the solvent) stay still."],"dp":[]},"physics1-migration:e4":{"s":0,"u":["Centrifugal acceleration γ = ω²R ≫ g.","External causes (gravity, centrifugal acceleration, electric field) or internal ones (concentration gradient: diffusion) drive them, always opposed by viscous drag."],"dp":[]},"physics1-migration:e1":{"s":1,"u":["Stokes: R = −6πrηv for a sphere; velocity becomes constant.","Stokes' law: R = −k·η·v (k depends on shape); for a sphere of radius r, R = −6πrηv .","The drag grows until it balances the driving force, after which velocity is constant."],"dp":[]},"physics1-migration:e2":{"s":1,"u":["Sedimentation force = V·g(ρ_s − ρ₀) (weight − Archimedes).","Sedimentation (gravity): the driving force is the apparent weight, F = V·g(ρ_s − ρ₀) (weight minus Archimedes' thrust), so the limit velocity rises with particle size and density difference and falls with viscosity."],"dp":[]},"physics1-migration:e3":{"s":1,"u":["ESR: plasma height after 1 h; normal < 10 mm; ↑ inflammation.","Erythrocyte sedimentation rate (ESR) : in anticoagulated blood in a vertical tube, the height of red-cell-free plasma after 1 hour (control at 2 h); normally ; raised in infection and inflammation."],"dp":[{"h":"Why the ESR rises in inflammation","t":"Inflammation raises plasma fibrinogen and globulins, which reduce the negative repulsion between red cells so they stack into rouleaux. A stack is a much bigger particle, and by Stokes' law larger particles settle faster, so the plasma column clears more quickly: a high ESR. Source: the lecture's sedimentation and ESR slides, and the viscosity lecture."}]},"physics1-migration:e5":{"s":2,"u":["Electric field: F = qE; v = uE; flux Φ = C·S·v.","The flux of particles through a surface S: Φ = C·S·v (positive ions move with the field, negative ions against it).","In an electric field , a charged particle feels F = q·E opposed by drag; it quickly reaches a constant velocity v = u·E (u = electrical mobility)."],"dp":[]},"physics1-migration:e6":{"s":2,"u":["Electrophoresis separates proteins by charge, size, shape.","Electrophoresis : macro-ions (proteins) in a field move at different speeds and are separated (e.g. serum protein electrophoresis)."],"dp":[]}},"meta":{"jfijvx":{"a":"recall","vg":"physics1-migration:e0/recall/1"},"1ayoz0c":{"a":"recall","vg":"physics1-migration:e1/recall/1"},"k5vjp9":{"a":"recall","vg":"physics1-migration:e1/recall/2"},"y86zre":{"a":"recall","vg":"physics1-migration:e2/recall/1"},"90jfcg":{"a":"recall","vg":"physics1-migration:e3/recall/1"},"bwa2sv":{"a":"recall","vg":"physics1-migration:e3/recall/2"},"r6xztv":{"a":"recall","vg":"physics1-migration:e4/recall/1"},"v5siux":{"a":"recall","vg":"physics1-migration:e5/recall/1"},"1omffzz":{"a":"recall","vg":"physics1-migration:e5/recall/2"},"19z431h":{"a":"recall","vg":"physics1-migration:e6/recall/1"}},"explRev":"4727012c71c9"};
